func TestLoadThresholdsFallsBack(t *testing.T) {
	dir := t.TempDir()
	write := func(name, content string) string {
		path := filepath.Join(dir, name)
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}

	cases := []struct {
		name string
		path string
	}{
		{"文件不存在", filepath.Join(dir, "missing.json")},
		{"读不出来", dir},
		{"不是 JSON", write("invalid.json", "not json")},
		{"不是对象（数组）", write("array.json", "[1,2]")},
		{"不是对象（字符串）", write("string.json", `"shanghai"`)},
		{"是 null", write("null.json", "null")},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := loadThresholds(tc.path); got != nil {
				t.Fatalf("loadThresholds(%q) = %v, 期望 nil 以便回退默认值", tc.path, got)
			}
		})
