// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsPath 返回仓库的 config/thresholds.json 路径。
//
// 配置文件在仓库根，而从 inventory/ 跑的测试 CWD 是包目录，所以两个相对位置都试，
// 取第一个存在的；都不存在时返回仓库根相对路径，读取失败由调用方回退默认值。
func thresholdsPath() string {
	candidates := []string{
		filepath.Join("config", "thresholds.json"),
		filepath.Join("..", "config", "thresholds.json"),
	}
	for _, path := range candidates {
		if _, err := os.Stat(path); err == nil {
			return path
		}
	}
	return candidates[0]
}

// loadThresholds 读取 path 里按仓库配置的阈值。
//
// 文件不存在、读不出来、或内容不是 JSON 对象时返回 nil，调用方回退默认值。
func loadThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// LowStockThreshold 返回这个仓库的低库存阈值；没配置时用 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds(thresholdsPath())[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}
